.roof-measured-lines li {
  align-items: center;
  background: var(--sf-surface);
  border: 1px solid color-mix(in oklab, var(--sf-border) 75%, white);
  border-radius: 0.5rem;
  display: grid;
  gap: 0.35rem;
  grid-template-columns: minmax(4rem, 0.8fr) minmax(5.5rem, 1fr) auto auto;
  padding: 0.35rem 0.45rem;
}

.roof-measured-lines li.is-incomplete {
  background: var(--sf-danger-soft);
  border-color: var(--sf-danger-border);
}

.roof-measured-lines li.is-incomplete span {
  flex-wrap: wrap;
}

.roof-line-incomplete-flag {
  color: var(--sf-danger-text);
  font-size: 0.62rem;
  font-style: normal;
  font-weight: 900;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.roof-measured-lines li.is-incomplete select {
  border-color: var(--sf-danger-border);
  color: var(--sf-danger-text);
}

